#include <stdlib.h>

int main(void) {
    int *p = NULL;
    int x = *p;            // read address 0: unmapped, so a segfault

    int *nums = malloc(3 * sizeof(int));
    free(nums);
    nums[0] = 42;          // use after free: undefined behavior,
                           // may crash or silently corrupt memory

    int arr[3] = {1, 2, 3};
    arr[10] = 7;           // out of bounds: C does not check
    return x;
}

// Python turns the same mistakes into exceptions:
//   None.value       -> AttributeError
//   [1, 2, 3][10]    -> IndexError: list index out of range

